style.css:
/* i really want this to be global */

:root {
  --system-background-light: #2B2E38;
  --system-background-dark: #19191D;
 
	--active-background-light: #FF0066;
  --active-background-dark: #EE0060;
  
  --gray-80-light: #666666;
  --gray-80-dark: #BEBFC5;
}

body .links .mat-divider {
  --mat-divider-color: var(--gray-80-light);
}

body .lyt-toolbar .main-avatar .avatar .user-avatar {
  border: 2px solid var(--brand-pink)
}





html body {
	--system-background: var(--system-background-light);
	--active-background: var(--active-background-light)
}

html body .bdz-lyt-root {
	background-size: cover;
	background-image: url("https://i.ibb.co/XYK3BTs/light-bg.png");
}





html[theme="dark"] body {
	--system-background: var(--system-background-dark);
	--active-background: var(--active-background-dark)
}

html[theme="dark"] body .bdz-lyt-root {
	background-size: cover;
  background-image: url("https://i.ibb.co/kHBf9Jh/dark-bg.png");
}
